static double maxeff(const X *x, const double *j) {   // max |Q (x - j)| over both axes
    double m = 0;
    for (int a = 0; a < 2; a++)
        for (int i = 0; i < N; i++) {
            double e = 0;
            for (int k = 0; k < N; k++) e += Q[i][k] * (x[a * N + k].to_double() - j[a * N + k]);
            m = fmax(m, fabs(e));
        }
    return m;
}

